// Janela de 2 h que se SOBREPÕE entre execuções: sem estado no n8n (sem staticData).
// A idempotência fica no CRM (Idempotency-Key + índice do leadgen id).
const desde = Math.floor(Date.now() / 1000) - 2 * 60 * 60;
return [{ json: { desde } }];

// Um item por lead. Corpo DETERMINÍSTICO (AC10): só campos estáveis,
// field_data ordenado por nome, nenhum carimbo de hora desta execução.
const leads = $input.first().json.data || [];
const semPrefixo = (v) => String(v ?? '').trim().replace(/^[a-z]{1,3}:/i, '');
return leads.map((l) => {
  const corpo = {
    leadgen_id: semPrefixo(l.id),
    created_time: l.created_time,
    field_data: [...(l.field_data || [])]
      .map((f) => ({ name: f.name, values: (f.values || []).map((v) => f.name === 'phone_number' ? semPrefixo(v) : v) }))
      .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)),
  };
  for (const k of ['form_id', 'campaign_id', 'campaign_name', 'ad_id', 'ad_name']) {
    const v = k.endsWith('_id') ? semPrefixo(l[k]) : String(l[k] ?? '').trim();
    if (v) corpo[k] = v;
  }
  return { json: corpo };
});

// M2 do QA: resposta >= 400 do CRM FALHA a execução (vai para o Error Workflow).
// Só 'IDEMPOTENCY_IN_PROGRESS' (a mesma chave ainda em curso) é esperado.
// 202 = aguardando a carência (reenviado na próxima execução). Só contagens: sem dado pessoal.
const contagem = {};
let recusados = 0;
for (const item of $input.all()) {
  const r = item.json;
  const code = r.body && r.body.code;
  const acao = (r.body && (r.body.acao || code)) || 'sem_acao';
  const k = String(r.statusCode) + ' ' + acao;
  contagem[k] = (contagem[k] || 0) + 1;
  if (r.statusCode >= 400 && code !== 'IDEMPOTENCY_IN_PROGRESS') recusados += 1;
}
if (recusados > 0) {
  throw new Error('Formulário Meta → CRM: ' + recusados + ' lead(s) recusados. Contagem: ' + JSON.stringify(contagem));
}
return [{ json: { processados: $input.all().length, contagem } }];

// Leads de 6 h atrás até 20 min atrás: já passaram da carência (10 min) + 1 ciclo de 5 min.
const agora = Math.floor(Date.now() / 1000);
return [{ json: { desde: agora - 6 * 60 * 60, ate: agora - 20 * 60 } }];

// Um item por lead. Corpo DETERMINÍSTICO (AC10): só campos estáveis,
// field_data ordenado por nome, nenhum carimbo de hora desta execução.
const leads = $input.first().json.data || [];
const semPrefixo = (v) => String(v ?? '').trim().replace(/^[a-z]{1,3}:/i, '');
return leads.map((l) => {
  const corpo = {
    leadgen_id: semPrefixo(l.id),
    created_time: l.created_time,
    field_data: [...(l.field_data || [])]
      .map((f) => ({ name: f.name, values: (f.values || []).map((v) => f.name === 'phone_number' ? semPrefixo(v) : v) }))
      .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)),
  };
  for (const k of ['form_id', 'campaign_id', 'campaign_name', 'ad_id', 'ad_name']) {
    const v = k.endsWith('_id') ? semPrefixo(l[k]) : String(l[k] ?? '').trim();
    if (v) corpo[k] = v;
  }
  return { json: corpo };
});

// Meta × CRM: todo lead da janela já deveria ser 'ja_processado' no CRM.
// Qualquer outra resposta (inclusive 401/5xx do próprio CRM) conta como faltando. Só contagens.
const contagem = {};
let faltando = 0;
for (const item of $input.all()) {
  const r = item.json;
  const acao = (r.body && (r.body.acao || r.body.code)) || 'sem_acao';
  const k = String(r.statusCode) + ' ' + acao;
  contagem[k] = (contagem[k] || 0) + 1;
  if (!(r.statusCode === 200 && acao === 'ja_processado')) faltando += 1;
}
return [{ json: { total: $input.all().length, faltando, contagem: JSON.stringify(contagem) } }];
